sigset_t pending_mask;
size_t set_bytes = sizeof(sigset_t);
int syscall_ret;

// Examine signals pending for the thread (rt_sigpending handles large sets)
syscall_ret = rt_sigpending(
    &pending_mask,
    set_bytes
);

// syscall_ret == 0 on success.
// If failure, check errno (e.g., EFAULT)
// Use sigismember() to check specific signals in pending_mask
// Example: if (sigismember(&pending_mask, SIGTERM)) { ... }
